mapper.select:
SELECT s.id AS subjectId, s.name, s.name_cn AS nameCn, s.type, s.nsfw, (s.import_status = 1) AS active, s.bangumi_id AS sourceId, CONCAT('https://bgm.tv/subject/', s.bangumi_id) AS sourceUrl, s.score, s.`rank`, s.rating_total AS ratingTotal, s.collection_total AS collectionTotal, s.air_date AS airDate, s.summary, s.source_fetched_at AS sourceFetchedAt FROM subject s WHERE s.id IN
#{id}
AND s.type = 2 AND s.nsfw = 0 AND s.import_status = 1

SELECT spc.subject_id AS subjectId, p.name AS personName, spc.role, spc.relation FROM subject_person_credit spc INNER JOIN person p ON p.id = spc.person_id WHERE spc.source_active = 1 AND p.source_active = 1 AND spc.subject_id IN
#{id}
ORDER BY spc.sort_order ASC

SELECT sc.subject_id AS subjectId, c.name AS characterName, sc.relation FROM subject_character sc INNER JOIN `character` c ON c.id = sc.character_id WHERE sc.source_active = 1 AND c.source_active = 1 AND sc.subject_id IN
#{id}
ORDER BY sc.sort_order ASC

SELECT sr.subject_id AS subjectId, sr.related_subject_id AS relatedSubjectId, rs.name AS relatedSubjectName, rs.name_cn AS relatedSubjectNameCn, sr.relation FROM subject_relation sr INNER JOIN subject rs ON rs.id = sr.related_subject_id WHERE sr.subject_id IN
#{id}
AND rs.type = 2 AND rs.nsfw = 0 AND rs.import_status = 1

SELECT s.id FROM subject_person_credit spc INNER JOIN person p ON p.id = spc.person_id INNER JOIN subject s ON s.id = spc.subject_id WHERE spc.source_active = 1 AND p.source_active = 1 AND s.type = 2 AND s.nsfw = 0 AND s.import_status = 1 AND spc.person_id IN
#{id}
GROUP BY s.id, s.score ORDER BY s.score DESC, s.id ASC

SELECT s.id FROM subject_character sc INNER JOIN `character` c ON c.id = sc.character_id INNER JOIN subject s ON s.id = sc.subject_id WHERE sc.source_active = 1 AND c.source_active = 1 AND s.type = 2 AND s.nsfw = 0 AND s.import_status = 1 AND sc.character_id IN
#{id}
GROUP BY s.id, s.score ORDER BY s.score DESC, s.id ASC

SELECT s.id FROM character_actor ca INNER JOIN person p ON p.id = ca.person_id INNER JOIN `character` c ON c.id = ca.character_id INNER JOIN subject s ON s.id = ca.subject_id WHERE ca.source_active = 1 AND p.source_active = 1 AND c.source_active = 1 AND s.type = 2 AND s.nsfw = 0 AND s.import_status = 1 AND ca.person_id IN
#{id}
GROUP BY s.id, s.score ORDER BY s.score DESC, s.id ASC

SELECT DISTINCT related.subject_id FROM ( SELECT sr.related_subject_id AS subject_id FROM subject_relation sr INNER JOIN subject related ON related.id = sr.related_subject_id WHERE sr.subject_id IN
#{id}
AND related.type = 2 AND related.nsfw = 0 AND related.import_status = 1 UNION SELECT sr.subject_id AS subject_id FROM subject_relation sr INNER JOIN subject related ON related.id = sr.subject_id WHERE sr.related_subject_id IN
#{id}
AND related.type = 2 AND related.nsfw = 0 AND related.import_status = 1 ) related ORDER BY related.subject_id ASC
